const data = await ctx.call("records", {});
console.log(data);
const totals = Object.fromEntries(data.owners.map(owner => [owner.name, 0]));
for (const record of data.records) {
  if (record.active && Object.hasOwn(totals, record.group)) totals[record.group] += record.value;
}
ctx.done(totals);
